// Rows in other tables that reference a paragraph (content.id) — what happens to them when a re-ingest removes that
// paragraph. Without this the ingester's DELETE failed on FOREIGN KEY constraints (2026-10-09: re-ingesting library files
// whose PDF-broken paragraphs were re-joined), and its batched deletes could leave a document half-removed.
//   null     — the column is nullable: keep the row, drop the link
//   delete   — derived data, regenerated by its pipeline on the new paragraphs
//   reattach — user-facing (saved research quotes): moved to the new paragraph that contains the old text
// paragraph_embeddings is ON DELETE CASCADE already. Pure statement builders + one matcher; the ingester runs them.

export const DEPENDENTS = [
  { table: 'enrichment_pending', col: 'content_id', action: 'delete' },
  { table: 'paragraph_roles', col: 'content_id', action: 'delete' },
  { table: 'quote_instances', col: 'content_id', action: 'delete' },
  { table: 'paragraph_extractions', col: 'content_id', action: 'delete' },
  { table: 'entity_mentions', col: 'content_id', action: 'delete' },
  { table: 'set_members', col: 'source_paragraph_id', action: 'null' },
  { table: 'significance_markers', col: 'source_paragraph_id', action: 'null' },
  { table: 'pending_bridge_relations', col: 'evidence_paragraph_id', action: 'null' },
  { table: 'deep_research_quotes', col: 'para_id', action: 'reattach' },
];

/** Statements that free `ids` for deletion (run in the SAME transaction as the DELETE FROM content). `tables`: the
 *  tables that exist (a fresh or test database may lack some). */
export function detachStatements(ids, tables = null) {
  if (!ids.length) return [];
  const ph = ids.map(() => '?').join(',');
  return DEPENDENTS.filter((d) => !tables || tables.has(d.table)).map((d) => (d.action === 'null'
    ? { sql: `UPDATE ${d.table} SET ${d.col} = NULL WHERE ${d.col} IN (${ph})`, args: ids }
    : { sql: `DELETE FROM ${d.table} WHERE ${d.col} IN (${ph})`, args: ids }));
}

const norm = (t) => String(t || '').normalize('NFC').replace(/<pb[^>]*\/>/g, ' ').replace(/[^\p{L}\p{N}]+/gu, ' ').trim().toLowerCase();

/** The new paragraph a removed one's text went into: the first whose text contains the old opening (≥ 40 chars of it). */
export function findSuccessor(oldText, newParagraphs) {
  const key = norm(oldText).slice(0, 80);
  if (key.length < 20) return null;
  const hit = newParagraphs.find((p) => norm(p.text).includes(key));
  return hit ? hit.id : null;
}

/** INSERT statements re-creating stashed rows on their successor paragraphs (rows with no successor are reported). */
export function reattachStatements(stash, newParagraphs) {
  const out = [], lost = [];
  for (const { table, col, row, oldText } of stash) {
    const to = findSuccessor(oldText, newParagraphs);
    if (!to) { lost.push({ table, id: row.id }); continue; }
    const cols = Object.keys(row).filter((c) => c !== 'id');
    out.push({ sql: `INSERT INTO ${table} (${cols.join(', ')}) VALUES (${cols.map(() => '?').join(', ')})`, args: cols.map((c) => (c === col ? to : row[c])) });
  }
  return { statements: out, lost };
}
